948	// coordinationPath 返回数据文件对应的协调文件（锁文件）路径。
949	// 相对、绝对及含 .、.. 的写法先归一到同一绝对路径，已存在的符号链接也被解析，
950	// 确保同一台账的不同路径写法共用同一把锁；首次创建不存在的台账同样适用。
951	func coordinationPath(path string) (string, error) {
952		abs, err := filepath.Abs(path)
953		if err != nil {
954			return "", fmt.Errorf("解析数据文件路径失败: %w", err)
955		}
956		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
957			abs = resolved
958		} else if dir, derr := filepath.EvalSymlinks(filepath.Dir(abs)); derr == nil {
959			abs = filepath.Join(dir, filepath.Base(abs))
960		}
961		return abs + ".lock", nil
962	}
963	
964	// OpenForUpdate 在进程间排他协调下打开台账，供会改写台账的命令使用：
965	// 先取得该台账的锁（其他终端正在作业时等待其完成），再在锁内读取最新已提交
966	// 数据；调用方随后完成的受理、去重与整次保存都在最新数据上进行，并行效果
967	// 等同于某个逐次执行顺序。返回的 release 必须在本次命令结束时调用（无论成败）。
968	// 锁由操作系统随文件描述符管理，持有者进程被强制终止时自动释放，
969	// 无需人工删除协调文件即可继续作业。
970	func OpenForUpdate(path string) (s *Store, release func(), err error) {
971		lockPath, err := coordinationPath(path)
972		if err != nil {
973			return nil, nil, err
974		}
975		if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
976			return nil, nil, fmt.Errorf("准备协调文件失败: %w", err)
977		}
978		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
979		if err != nil {
980			return nil, nil, fmt.Errorf("打开协调文件失败: %w", err)
981		}
982		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
983			_ = lock.Close()
984			return nil, nil, fmt.Errorf("等待台账协调锁失败: %w", err)
985		}
986		release = func() {
987			_ = syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
988			_ = lock.Close()
989		}
990		s, err = Open(path)
991		if err != nil {
992			release()
993			return nil, nil, err
994		}
995		return s, release, nil
996	}
