998	// Register 执行单件收件登记并将结果整体落盘。
999	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
1000		if _, ok := s.data.Parcels[id]; ok {
1001			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
1002		}
1003		p := &Parcel{
1004			ID:         id,
1005			Station:    station,
1006			Status:     statusInStation,
1007			Registered: now,
1008			Trail: []Event{{
1009				Op:      "收件",
1010				Station: station,
1011				Time:    now,
1012			}},
1013		}
1014		s.data.Parcels[id] = p
1015		if err := s.save(); err != nil {
1016			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
1017			return nil, err
1018		}
1019		return p, nil
1020	}
