1043	// Handoff 提交一次多件包裹的站点交接。
1044	//
1045	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
1046	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
1047	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
1048	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
1049	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
1050		if saved, ok := s.data.Handoffs[request]; ok {
1051			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
1052				return saved, true, nil
1053			}
1054			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
1055		}
1056	
1057		// 首次提交：先做全部校验，任何一件不满足都整体失败。
1058		for _, id := range parcels {
1059			p, ok := s.data.Parcels[id]
1060			if !ok {
1061				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
1062			}
1063			if p.Station != from {
1064				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
1065			}
1066			if inc := activeFreeze(p); inc != "" {
1067				return nil, false, fmt.Errorf("交接失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批交接拒绝，整次交接未执行", id, inc)
1068			}
1069			if p.Status != statusInStation {
1070				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
1071			}
1072		}
1073	
1074		res := &HandoffResult{
1075			Request: request,
1076			From:    from,
1077			To:      to,
1078			Parcels: append([]string(nil), parcels...),
1079			Time:    now,
1080		}
1081		s.data.Handoffs[request] = res
1082	
1083		// 记录旧值，落盘失败时整体回滚。
1084		prev := make(map[string]struct {
1085			station string
1086			trail   []Event
1087		}, len(parcels))
1088		for _, id := range parcels {
1089			p := s.data.Parcels[id]
1090			prev[id] = struct {
1091				station string
1092				trail   []Event
1093			}{p.Station, append([]Event(nil), p.Trail...)}
1094			p.Station = to
1095			p.Status = statusInStation
1096			p.Trail = append(p.Trail, Event{
1097				Op:      "交接",
1098				Station: to,
1099				Request: request,
1100				Time:    now,
1101			})
1102		}
1103	
1104		if err := s.save(); err != nil {
1105			delete(s.data.Handoffs, request)
1106			for id, old := range prev {
1107				p := s.data.Parcels[id]
1108				p.Station = old.station
1109				p.Trail = old.trail
1110			}
1111			return nil, false, err
1112		}
1113		return res, false, nil
1114	}
