1211	// Dispatch 提交一次配送批次出站。
1212	//
1213	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
1214	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
1215	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
1216	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
1217	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
1218	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
1219		if saved, ok := s.data.Batches[batch]; ok {
1220			if saved.RelayedFrom != "" {
1221				return nil, false, fmt.Errorf("批次号 %q 已由续接 %q 创建（来源批次 %q），不能用于出站，内容冲突",
1222					batch, saved.RelayRequest, saved.RelayedFrom)
1223			}
1224			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
1225				return saved, true, nil
1226			}
1227			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
1228		}
1229	
1230		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
1231		for _, id := range parcels {
1232			p, ok := s.data.Parcels[id]
1233			if !ok {
1234				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
1235			}
1236			if p.Station != station {
1237				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
1238			}
1239			if inc := activeFreeze(p); inc != "" {
1240				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
1241			}
1242			if p.Status != statusInStation {
1243				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
1244			}
1245		}
1246	
1247		res := &BatchResult{
1248			Batch:    batch,
1249			Station:  station,
1250			Courier:  courier,
1251			Parcels:  append([]string(nil), parcels...),
1252			Time:     now,
1253			Receipts: map[string]*ReceiptEntry{},
1254		}
1255		s.data.Batches[batch] = res
1256	
1257		// 记录旧值，落盘失败时整体回滚。
1258		prev := make(map[string]struct {
1259			status string
1260			trail  []Event
1261		}, len(parcels))
1262		for _, id := range parcels {
1263			p := s.data.Parcels[id]
1264			prev[id] = struct {
1265				status string
1266				trail  []Event
1267			}{p.Status, append([]Event(nil), p.Trail...)}
1268			p.Status = statusDelivering // 站点不变，仍记出发站
1269			p.Trail = append(p.Trail, Event{
1270				Op:      "出站",
1271				Station: station,
1272				Batch:   batch,
1273				Courier: courier,
1274				Time:    now,
1275			})
1276		}
1277	
1278		if err := s.save(); err != nil {
1279			delete(s.data.Batches, batch)
1280			for id, old := range prev {
1281				p := s.data.Parcels[id]
1282				p.Status = old.status
1283				p.Trail = old.trail
1284			}
1285			return nil, false, err
1286		}
1287		return res, false, nil
1288	}
