1394	// ReceiptImportRecord 是回执整批导入文件中的一条记录（已清洗）。
1395	type ReceiptImportRecord struct {
1396		Request string // 回执请求号（与逐件 receipt 共用去重范围）
1397		Batch   string // 配送批次号
1398		Parcel  string // 包裹编号
1399		Result  string // 签收 | 失败
1400		Reason  string // 失败原因（失败时非空，签收时为空）
1401	}
1402	
1403	// ReceiptImportItem 是整批导入中一条记录的处理结果，按文件顺序排列。
1404	type ReceiptImportItem struct {
1405		Record   ReceiptImportRecord // 清洗后的记录内容
1406		Time     time.Time           // 发生时间（重放时为首次保存的时间）
1407		Replayed bool                // true 表示同内容历史重放，未产生新变更
1408		Revoked  bool                // true 表示该回执已被撤销（仅历史重放可能；重放不恢复回执）
1409	}
1410	
1411	// ImportReceipts 按文件顺序整批应用回执记录。
1412	//
1413	// 逐条处理：与逐件 Receipt 共用同一回执请求号去重范围，同请求号且批次、包裹、
1414	// 结果、清理后的原因相同的记录返回首次结果与时间（重放），不检查当前状态、不追加
1415	// 轨迹、不改变批次进度；换内容报冲突。首次回执要求批次存在、包裹属于该批次、
1416	// 尚未在该批次回执且当前仍在该批次配送中（含本文件前面记录已产生的回执）。
1417	// 全部记录可接受时作为一个整体原子落盘；任一记录无效、冲突或受理条件不符，
1418	// 整份拒绝并提示记录位置，台账保持导入前状态，新请求号均不占用。
1419	// 全部为历史重放时不改写台账。
1420	func (s *Store) ImportReceipts(records []ReceiptImportRecord, now time.Time) ([]ReceiptImportItem, error) {
1421		// 在台账副本上按文件顺序试算：任一记录失败直接放弃副本，原台账保持不变。
1422		work, err := s.fork()
1423		if err != nil {
1424			return nil, err
1425		}
1426		items := make([]ReceiptImportItem, 0, len(records))
1427		hasNew := false
1428		for i, rec := range records {
1429			res, replayed, _, err := work.applyReceipt(rec.Request, rec.Batch, rec.Parcel, rec.Result, rec.Reason, now)
1430			if err != nil {
1431				return nil, fmt.Errorf("第 %d 条记录（请求号 %q）：%w", i+1, rec.Request, err)
1432			}
1433			if !replayed {
1434				hasNew = true
1435			}
1436			items = append(items, ReceiptImportItem{Record: rec, Time: res.Time, Replayed: replayed, Revoked: res.RevokedBy != ""})
1437		}
1438		if !hasNew {
1439			return items, nil // 全部为历史重放：不改写台账
1440		}
1441	
1442		// 整体提交：副本替换当前台账后一次原子落盘，失败时恢复导入前状态。
1443		orig := s.data
1444		s.data = work.data
1445		if err := s.save(); err != nil {
1446			s.data = orig
1447			return nil, err
1448		}
1449		return items, nil
1450	}
1451	
1452	// fork 返回当前台账的深拷贝副本，供整批导入试算；副本上的任何改动都不影响原台账。
1453	func (s *Store) fork() (*Store, error) {
1454		buf, err := json.Marshal(s.data)
1455		if err != nil {
1456			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1457		}
1458		var cp ledgerFile
1459		if err := json.Unmarshal(buf, &cp); err != nil {
1460			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1461		}
1462		return &Store{path: s.path, data: cp}, nil
1463	}
1464	
1465	// RevokeReceipt 撤销一条误录的配送回执：经核实包裹实际仍由原配送员配送，
1466	// 撤销错误的签收或失败登记，不收回实物。包裹与批次取自原回执，不可另选。
1467	//
1468	// 首次撤销：原回执必须存在、未撤销且仍为该件在该批次的有效回执；所属批次
1469	// 未中止、未转交；原回执必须是该包裹最后一条轨迹（其后发生过流转、冻结或
1470	// 解除均拒绝，其他成员的后续操作不阻止撤销），包裹仍在原出发站且状态与回执
1471	// 结果一致。任一不满足则拒绝，不作任何改动。成功后该件恢复原批次配送中，
1472	// 站点、配送员不变，该回执不再计入有效回执（原本已完成的批次恢复配送中，
1473	// 原成员顺序与出站或接手时间保留，其他成员及回执不变）；原回执结果与轨迹
1474	// 永久保留并标记已撤销，追加一条撤销回执记录，回执请求号不删除也不释放。
1475	// 每件同批次最多一条未撤销回执，撤销后可用新回执请求号再次提交签收或失败，
1476	// 也可随原批次中止或续接。撤销不恢复配送前旧交接的退回资格。
1477	// 撤销请求号独立去重，可与其他业务编号同名：相同请求号且原回执、清理后的
1478	// 原因相同，直接返回首次撤销信息和时间，replayed 为 true，不检查现状、不
1479	// 再次改变进度或改写台账（后续重新回执、中止或续接后仍成立）；请求号相同
1480	// 但内容不同报冲突。每条原回执只能撤销一次，换撤销号再次撤销它拒绝；
1481	// 失败的首次撤销不占用请求号。
1482	func (s *Store) RevokeReceipt(request, receiptReq, reason string, now time.Time) (res *RevokeResult, replayed bool, err error) {
1483		if saved, ok := s.data.Revokes[request]; ok {
1484			if saved.Receipt == receiptReq && saved.Reason == reason {
1485				return saved, true, nil
1486			}
1487			return nil, false, fmt.Errorf("撤销请求号 %q 已用于一次不同的撤销（原回执=%q 原因=%q），内容冲突",
1488				request, saved.Receipt, saved.Reason)
1489		}
1490	
1491		rc, ok := s.data.Receipts[receiptReq]
1492		if !ok {
1493			return nil, false, fmt.Errorf("撤销失败：原回执请求号 %q 不存在", receiptReq)
1494		}
1495		if rc.RevokedBy != "" {
1496			return nil, false, fmt.Errorf("撤销失败：原回执 %q 已撤销（撤销请求号 %q），每条原回执只能撤销一次", receiptReq, rc.RevokedBy)
1497		}
1498		b := s.data.Batches[rc.Batch] // 回执所属批次必存在（载入校验保证）
1499		if b.AbortedBy != "" {
1500			return nil, false, fmt.Errorf("撤销失败：批次 %q 已中止（中止请求号 %q），不能撤销其中的回执", rc.Batch, b.AbortedBy)
1501		}
1502		if b.TransferredBy != "" {
1503			return nil, false, fmt.Errorf("撤销失败：批次 %q 已转交（续接请求号 %q），不能撤销其中的回执", rc.Batch, b.TransferredBy)
1504		}
1505		entry := b.Receipts[rc.Parcel]
1506		if entry == nil || entry.Request != receiptReq {
1507			return nil, false, fmt.Errorf("撤销失败：回执 %q 已不是包裹 %q 在批次 %q 的有效回执", receiptReq, rc.Parcel, rc.Batch)
1508		}
1509		p := s.data.Parcels[rc.Parcel] // 批次成员必已登记（载入校验保证）
1510		last := p.Trail[len(p.Trail)-1]
1511		if last.Op != "回执" || last.Request != receiptReq {
1512			return nil, false, fmt.Errorf("撤销失败：包裹 %q 在原回执 %q 之后又发生流转、冻结或解除，不能撤销该回执", rc.Parcel, receiptReq)
1513		}
1514		if p.Station != b.Station {
1515			return nil, false, fmt.Errorf("撤销失败：包裹 %q 当前归属 %q，不在原出发站 %q，不能撤销该回执", rc.Parcel, p.Station, b.Station)
1516		}
1517		want := statusSigned
1518		if rc.Result == resultFailed {
1519			want = statusInStation
1520		}
1521		if p.Status != want {
1522			return nil, false, fmt.Errorf("撤销失败：包裹 %q 当前状态为 %q，与原回执 %q 的结果 %q 不一致，不能撤销",
1523				rc.Parcel, p.Status, receiptReq, rc.Result)
1524		}
1525	
1526		res = &RevokeResult{
1527			Request: request,
1528			Receipt: receiptReq,
1529			Batch:   rc.Batch,
1530			Parcel:  rc.Parcel,
1531			Reason:  reason,
1532			Time:    now,
1533		}
1534		s.data.Revokes[request] = res
1535		rc.RevokedBy = request
1536		entry.RevokedBy = request
1537	
1538		// 记录旧值，落盘失败时整体回滚。
1539		oldStatus := p.Status
1540		oldTrailLen := len(p.Trail)
1541		p.Status = statusDelivering // 恢复原批次配送中，站点与配送员不变
1542		p.Trail = append(p.Trail, Event{
1543			Op:         "撤销回执",
1544			Station:    b.Station,
1545			Batch:      rc.Batch,
1546			Request:    request,
1547			RefRequest: receiptReq,
1548			Reason:     reason,
1549			Time:       now,
1550		})
1551	
1552		if err := s.save(); err != nil {
1553			delete(s.data.Revokes, request)
1554			rc.RevokedBy = ""
1555			entry.RevokedBy = ""
1556			p.Status = oldStatus
1557			p.Trail = p.Trail[:oldTrailLen]
1558			return nil, false, err
1559		}
1560		return res, false, nil
1561	}
1562	
1563	// ReceiptOf 按回执请求号返回回执结果；不存在时返回 nil。
1564	func (s *Store) ReceiptOf(request string) *ReceiptResult {
1565		return s.data.Receipts[request]
1566	}
1567	
1568	// RevokeOf 按撤销请求号返回撤销结果；不存在时返回 nil。
1569	func (s *Store) RevokeOf(request string) *RevokeResult {
1570		return s.data.Revokes[request]
1571	}
1572	
1573	// BatchRevokes 返回一个配送批次相关的全部撤销记录，按撤销时间升序。
1574	func (s *Store) BatchRevokes(batch string) []*RevokeResult {
1575		var out []*RevokeResult
1576		for _, rv := range s.data.Revokes {
1577			if rv.Batch == batch {
1578				out = append(out, rv)
1579			}
1580		}
1581		sort.Slice(out, func(i, j int) bool { return out[i].Time.Before(out[j].Time) })
1582		return out
1583	}
1584	
1585	// Freeze 对一件在站包裹登记异常冻结。
1586	//
1587	// 首次冻结：包裹必须已登记、当前归属指定站点且状态为在站；配送中、已签收或已冻结的
1588	// 包裹不能冻结。成功后站点不变，状态转为异常冻结，追加一条含异常单号、原因、站点和
1589	// 时间的冻结记录。一件包裹同时只能有一张未解除异常单。
1590	// 冻结只是管理记录，不移动实物、不算新流转。
1591	// 异常单号标识一次异常，解除后也不能复用：相同异常单号且包裹、站点、清理后的原因
1592	// 相同，直接返回首次冻结结果与时间，replayed 为 true，不再次冻结（即使该异常单已解除、
1593	// 包裹已发生新的流转，也不检查当前状态）；异常单号相同但内容不同报冲突；
1594	// 失败的首次冻结不占用异常单号。异常单号与包裹编号及其他业务编号分属独立去重范围。
1595	func (s *Store) Freeze(incident, parcel, station, reason string, now time.Time) (res *FreezeResult, replayed bool, err error) {
1596		if saved, ok := s.data.Freezes[incident]; ok {
1597			if saved.Parcel == parcel && saved.Station == station && saved.Reason == reason {
1598				return saved, true, nil
1599			}
1600			return nil, false, fmt.Errorf("异常单号 %q 已用于一次不同的冻结（包裹=%q 站点=%q 原因=%q），内容冲突",
1601				incident, saved.Parcel, saved.Station, saved.Reason)
1602		}
1603	
1604		p, ok := s.data.Parcels[parcel]
1605		if !ok {
1606			return nil, false, fmt.Errorf("冻结失败：包裹 %q 未登记，冻结未执行", parcel)
1607		}
1608		if p.Station != station {
1609			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前归属 %q，不在指定站点 %q，冻结未执行", parcel, p.Station, station)
1610		}
1611		if p.Status != statusInStation {
1612			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前状态为 %q，仅在站包裹可以冻结，冻结未执行", parcel, p.Status)
1613		}
1614	
1615		res = &FreezeResult{
1616			Incident: incident,
1617			Parcel:   parcel,
1618			Station:  station,
1619			Reason:   reason,
1620			Time:     now,
1621		}
1622		s.data.Freezes[incident] = res
1623	
1624		// 记录旧值，落盘失败时整体回滚。
1625		oldStatus := p.Status
1626		oldTrail := append([]Event(nil), p.Trail...)
1627		p.Status = statusFrozen // 站点不变
1628		p.Trail = append(p.Trail, Event{
1629			Op:       "冻结",
1630			Station:  station,
1631			Incident: incident,
1632			Reason:   reason,
1633			Time:     now,
1634		})
1635	
1636		if err := s.save(); err != nil {
1637			delete(s.data.Freezes, incident)
1638			p.Status, p.Trail = oldStatus, oldTrail
1639			return nil, false, err
1640		}
1641		return res, false, nil
1642	}
1643	
1644	// Unfreeze 解除一件包裹当前的异常冻结。
1645	//
1646	// 首次解除：异常单必须存在且尚未解除，并且仍是该包裹当前冻结对应的异常单；
1647	// 异常单不存在、已解除或对应关系不符均拒绝。成功后包裹在原站恢复在站，原异常单
1648	// 永久标记为已解除（异常单号不得复用），追加一条含异常单号、解除请求号、处理说明及
1649	// 时间的解除记录，原冻结记录不删改；之后可用新异常单再次冻结。
1650	// 解除只是管理记录，不移动实物、不算新流转。
1651	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名：相同解除请求号且异常单、
1652	// 处理说明相同，直接返回首次解除结果与时间，replayed 为 true，不检查当前状态，也不影响
1653	// 后来新建的异常单或后续流转；请求号相同但内容不同报冲突；失败的首次解除不占用请求号。
1654	func (s *Store) Unfreeze(request, incident, note string, now time.Time) (res *UnfreezeResult, replayed bool, err error) {
1655		if saved, ok := s.data.Unfreezes[request]; ok {
1656			if saved.Incident == incident && saved.Note == note {
1657				return saved, true, nil
1658			}
1659			return nil, false, fmt.Errorf("解除请求号 %q 已用于一次不同的解除（异常单=%q 处理说明=%q），内容冲突",
1660				request, saved.Incident, saved.Note)
1661		}
1662	
1663		f, ok := s.data.Freezes[incident]
1664		if !ok {
1665			return nil, false, fmt.Errorf("解除失败：异常单号 %q 不存在，解除未执行", incident)
1666		}
1667		if f.ReleasedBy != "" {
1668			return nil, false, fmt.Errorf("解除失败：异常单 %q 已解除（解除请求号 %q），不能重复解除", incident, f.ReleasedBy)
1669		}
1670		p, ok := s.data.Parcels[f.Parcel]
1671		if !ok {
1672			return nil, false, fmt.Errorf("解除失败：异常单 %q 对应的包裹 %q 不存在，解除未执行", incident, f.Parcel)
1673		}
1674		if p.Status != statusFrozen || activeFreeze(p) != incident {
1675			return nil, false, fmt.Errorf("解除失败：异常单 %q 不是包裹 %q 当前冻结对应的异常单（当前异常单 %q），解除未执行",
1676				incident, f.Parcel, activeFreeze(p))
1677		}
1678	
1679		res = &UnfreezeResult{
1680			Request:  request,
1681			Incident: incident,
1682			Parcel:   f.Parcel,
1683			Note:     note,
1684			Time:     now,
1685		}
1686		s.data.Unfreezes[request] = res
1687		f.ReleasedBy = request
1688	
1689		// 记录旧值，落盘失败时整体回滚。
1690		oldStatus := p.Status
1691		oldTrail := append([]Event(nil), p.Trail...)
1692		p.Status = statusInStation // 在原站恢复在站，站点不变
1693		p.Trail = append(p.Trail, Event{
1694			Op:       "解除冻结",
1695			Station:  f.Station,
1696			Incident: incident,
1697			Request:  request,
1698			Note:     note,
1699			Time:     now,
1700		})
1701	
1702		if err := s.save(); err != nil {
1703			delete(s.data.Unfreezes, request)
1704			f.ReleasedBy = ""
1705			p.Status, p.Trail = oldStatus, oldTrail
1706			return nil, false, err
1707		}
1708		return res, false, nil
1709	}
1710	
1711	// Abort 中止一个配送批次：配送员已将该批次全部尚未回执的包裹实物收回出发站。
1712	// 成员与站点取自原批次结果，不允许另选成员或站点。
1713	//
1714	// 首次中止：批次必须存在、尚未完成且未中止，且至少有一件未回执成员；这些成员
1715	// 必须仍在原批次配送中、归属出发站，任一不符整批拒绝、不作任何改动。已回执成员

