82		// 同号、同两站、同集合（换序）重放：返回首次成员顺序与发运时间，不追加轨迹。
83		res, replayed, err := s.Ship("S1", "站点A", "站点B", []string{"P002", "P001"}, tClock(2026, 10, 5, 11, 0))
84		if err != nil || !replayed {
