141		for _, id := range []string{"P001", "P002"} {
142			p, _ := s.Query(id)
143			if p.Status != statusInStation || p.Station != "站点A" || len(p.Trail) != 1 {
144				t.Fatalf("失败的首次发运不应改变包裹 %q: status=%q station=%q trail=%d", id, p.Status, p.Station, len(p.Trail))
145			}
146		}
147		if _, err := s.ShipmentQuery("SX"); err == nil {
148			t.Fatalf("失败的首次发运不应占用运输单号")
149		}
150	
151		// 在途件不能再次发运（每件同时最多属于一张未接收运输单）。
152		mustShip(t, s, "S1", "站点A", "站点B", []string{"P001"}, tClock(2026, 10, 5, 10, 0))
153		if _, _, err := s.Ship("S2", "站点A", "站点C", []string{"P001", "P002"}, tClock(2026, 10, 5, 10, 30)); err == nil {
154			t.Fatalf("在途件应不能再次发运")
155		}
156		p2, _ := s.Query("P002")
157		if p2.Status != statusInStation || len(p2.Trail) != 1 {
158			t.Fatalf("整单拒绝不应改变其他包裹: %+v", p2)
159		}
160		if _, err := s.ShipmentQuery("S2"); err == nil {
161			t.Fatalf("失败的首次发运不应占用运输单号 S2")
162		}
163	}
