258		if _, _, err := s.Receive("RS1", "S2", "站点C", tClock(2026, 10, 5, 15, 0)); err == nil ||
259			!strings.Contains(err.Error(), "冲突") {
260			t.Fatalf("换运输单应报冲突: %v", err)
261		}
262		if _, _, err := s.Receive("RS1", "S1", "站点C", tClock(2026, 10, 5, 15, 0)); err == nil ||
263			!strings.Contains(err.Error(), "冲突") {
264			t.Fatalf("换接收站点应报冲突: %v", err)
