269			t.Fatalf("换请求号再次接收同一运输单应拒绝")
270		}
271	
272		// 接收请求号与运输单号及其他编号独立，可同名。
273		mustReceive(t, s, "S2", "S2", "站点C", tClock(2026, 10, 5, 16, 0))
