```go
// buildShippedLedger 建立 P001、P002 经 S1 从站点A 发往站点B 并已接收的有效台账，
// 返回数据文件路径与有效文件字节。
func buildShippedLedger(t *testing.T) (string, []byte) {
	t.Helper()
	s, path := openTempStore(t)
	setupShipBase(t, s)
	mustShip(t, s, "S1", "站点A", "站点B", []string{"P001", "P002"}, tClock(2026, 10, 5, 10, 0))
	mustReceive(t, s, "RS1", "S1", "站点B", tClock(2026, 10, 5, 12, 0))
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return path, raw
}

// mutateLedger 将 fn 应用到有效台账的 JSON 表示后写回，并断言重新打开被拒绝。
func mutateLedger(t *testing.T, path string, raw []byte, name string, fn func(m map[string]any)) {
	t.Helper()
	var m map[string]any
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatal(err)
	}
	fn(m)
	buf, err := json.Marshal(m)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, buf, 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := Open(path); !errors.Is(err, ErrCorrupt) {
		t.Fatalf("%s：应拒绝载入，得到 err=%v", name, err)
	}
}
```

