1	package main
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// buildReceivedLedger 建立 P001、P002 经运输单 S1 从站点A 发往站点B 并整单接收的
13	// 有效台账，返回数据文件路径与有效文件字节（供篡改后还原）。
14	func buildReceivedLedger(t *testing.T) (string, []byte) {
15		t.Helper()
16		s, path := openTempStore(t)
17		setupShipBase(t, s)
18		mustShip(t, s, "S1", "站点A", "站点B", []string{"P001", "P002"}, tClock(2026, 10, 5, 10, 0))
19		mustReceive(t, s, "RS1", "S1", "站点B", tClock(2026, 10, 5, 12, 0))
20		raw, err := os.ReadFile(path)
21		if err != nil {
22			t.Fatalf("读取数据文件失败: %v", err)
23		}
24		return path, raw
25	}
26	
27	// corruptLedger 把 fn 应用到有效台账字节的 JSON 表示上并写回，
28	// 断言重新载入被明确拒绝（ErrCorrupt，不崩溃、不报告成功）。
29	func corruptLedger(t *testing.T, path string, raw []byte, name string, fn func(m map[string]any)) {
30		t.Helper()
31		var m map[string]any
32		if err := json.Unmarshal(raw, &m); err != nil {
33			t.Fatalf("解析数据文件失败: %v", err)
34		}
35		fn(m)
36		buf, err := json.Marshal(m)
37		if err != nil {
38			t.Fatalf("编码失败: %v", err)
39		}
40		if err := os.WriteFile(path, buf, 0o644); err != nil {
41			t.Fatal(err)
42		}
43		if _, err := Open(path); !errors.Is(err, ErrCorrupt) {
44			t.Fatalf("%s：应明确拒绝载入，得到 err=%v", name, err)
45		}
46	}
47	
48	// restoreLedger 还原有效文件字节并断言可以正常打开。
49	func restoreLedger(t *testing.T, path string, raw []byte) {
50		t.Helper()
51		if err := os.WriteFile(path, raw, 0o644); err != nil {
52			t.Fatal(err)
53		}
54		if _, err := Open(path); err != nil {
55			t.Fatalf("还原有效文件后应能正常打开: %v", err)
56		}
57	}
58	
59	func ledgerParcel(m map[string]any, id string) map[string]any {
60		return m["parcels"].(map[string]any)[id].(map[string]any)
61	}
62	
63	func ledgerShipment(m map[string]any, no string) map[string]any {
64		return m["shipments"].(map[string]any)[no].(map[string]any)
65	}
66	
67	func ledgerReceive(m map[string]any, req string) map[string]any {
68		return m["receives"].(map[string]any)[req].(map[string]any)
69	}
70	
