72	func TestShipReceiveNullAssociationsRejected(t *testing.T) {
73		path, raw := buildReceivedLedger(t)
74	
75		corruptLedger(t, path, raw, "运输单结果为 null", func(m map[string]any) {
76			m["shipments"].(map[string]any)["S1"] = nil
77		})
78		corruptLedger(t, path, raw, "接收结果为 null", func(m map[string]any) {
79			m["receives"].(map[string]any)["RS1"] = nil
80		})
81		corruptLedger(t, path, raw, "包裹记录为 null", func(m map[string]any) {
82			m["parcels"].(map[string]any)["P001"] = nil
83		})
84		corruptLedger(t, path, raw, "运输单成员为 null", func(m map[string]any) {
85			ledgerShipment(m, "S1")["parcels"] = []any{"P001", nil}
86		})
87		corruptLedger(t, path, raw, "接收成员为 null", func(m map[string]any) {
88			ledgerReceive(m, "RS1")["parcels"] = []any{nil, "P002"}
89		})
90		corruptLedger(t, path, raw, "运输单成员缺失", func(m map[string]any) {
